-- Classic 1.60 (WoW Forever): spawns of the dungeon Ruins of Lordaeron (map 2999) from ymir sniffs of the official beta
-- (classic_re/sniff/sniff_import_instance.py): every placed creature and gameobject, merged over the instances seen; event
-- spawns (only seen being created in view) and summons are left to the scripts. Safe to run again.
DELETE FROM `creature` WHERE `map` = 2999 OR `guid` BETWEEN 21300000 AND 21399999;
DELETE FROM `gameobject` WHERE `map` = 2999 OR `guid` BETWEEN 21300000 AND 21399999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 21300000 AND 21399999;
DELETE FROM `waypoint_path_node` WHERE `PathId` BETWEEN 213000000 AND 213999999;
DELETE FROM `waypoint_path` WHERE `PathId` BETWEEN 213000000 AND 213999999;
-- patrols (walking routes the creature repeated in the sniff)
